package com.ruoyi.medical.persistence;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import com.ruoyi.medical.contracts.*;import org.springframework.mock.web.MockHttpServletResponse;
class FormalInvocationResponsesTest {
 @Test void immutableCancellationUsesRealPublishedEnvelopeAndExactHeaders()throws Exception{var json=new FormalInvocationSchema();var receipt=json.parse("{\"schema_version\":\"1.0.0\",\"invocation_id\":\"00000000-0000-4000-8000-000000000001\",\"verification_id\":\"00000000-0000-4000-8000-000000000002\",\"request_body_sha256\":\""+"a".repeat(64)+"\",\"original_key_sha256\":\""+"b".repeat(64)+"\",\"status\":\"CANCELLED\",\"before_dispatch\":true,\"reservations_released\":true,\"provider_termination_confirmed\":false,\"created_at\":\"2026-10-18T00:00:00Z\"}");new FormalInvocationHttpSchema(json).validate("CancelReceipt",receipt);var response=new MockHttpServletResponse();var actual=FormalInvocationResponses.envelope(receipt,"1",response);SchemaCatalogue.fromClasspath().validate("interfaces",actual,"Envelope");assertEquals("1",actual.required("resource_revision").textValue());assertFalse(actual.has("revision"));assertEquals(actual.required("request_id").textValue(),response.getHeader("X-Request-Id"));assertEquals("1.0.0",response.getHeader("X-Schema-Version"));assertEquals("no-store",response.getHeader("Cache-Control"));}
 @Test void absentOriginalCancellationIsTypedWithoutFabricatedRevision()throws Exception{var schema=new FormalInvocationHttpSchema(new FormalInvocationSchema());var data=new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode().put("found",false).putNull("receipt");schema.validate("CancelRecovery",data);var wire=FormalInvocationResponses.envelope(data,null,new MockHttpServletResponse());SchemaCatalogue.fromClasspath().validate("interfaces",wire,"Envelope");assertTrue(wire.required("resource_revision").isNull());data.put("found",true);assertThrows(TenantAccessException.class,()->schema.validate("CancelRecovery",data));}
 @Test void actualCancellationControllerReturnsPublishedEnvelope()throws Exception{
  var json=new FormalInvocationSchema();var schemas=new FormalInvocationHttpSchema(json);var identities=org.mockito.Mockito.mock(com.ruoyi.medical.identity.ApplicationSessionIdentity.class);var access=org.mockito.Mockito.mock(EnterpriseAccess.class);var cancellation=org.mockito.Mockito.mock(FormalInvocationCancellation.class);var controller=new FormalInvocationApplicationController(identities,access,cancellation,schemas);var http=new org.springframework.mock.web.MockHttpServletRequest();http.addHeader("X-Schema-Version","1.0.0");http.addHeader("X-Context-Revision","1");http.addHeader("Idempotency-Key","original-key/?#-0000");String id="00000000-0000-4000-8000-000000000001";http.setContent(("{\"schema_version\":\"1.0.0\",\"invocation_id\":\""+id+"\",\"reason\":\"Stop this test\"}").getBytes(java.nio.charset.StandardCharsets.UTF_8));var identity=org.mockito.Mockito.mock(com.ruoyi.medical.identity.ApplicationSessionIdentity.Verified.class);org.mockito.Mockito.when(identities.requireCurrent(http,null)).thenReturn(identity);var admission=org.mockito.Mockito.mock(EnterpriseAccess.Admission.class,org.mockito.Mockito.RETURNS_DEEP_STUBS);org.mockito.Mockito.when(admission.context().context_revision()).thenReturn("1");org.mockito.Mockito.when(access.execute(org.mockito.ArgumentMatchers.eq(identity),org.mockito.ArgumentMatchers.any())).thenAnswer(call->((java.util.function.Function<EnterpriseAccess.Admission,Object>)call.getArgument(1)).apply(admission));
  var receipt=new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode().put("schema_version","1.0.0").put("invocation_id",id).put("verification_id",id).put("request_body_sha256","a".repeat(64)).put("original_key_sha256","b".repeat(64)).put("status","CANCELLED").put("before_dispatch",true).put("reservations_released",true).put("provider_termination_confirmed",false).put("created_at","2026-10-18T00:00:00Z");org.mockito.Mockito.when(cancellation.cancel(admission,id,"original-key/?#-0000","Stop this test")).thenReturn(receipt);var response=new MockHttpServletResponse();var wire=controller.cancel(http,response,null);SchemaCatalogue.fromClasspath().validate("interfaces",wire,"Envelope");schemas.validate("CancelReceipt",wire.required("data"));assertEquals("1",wire.required("resource_revision").textValue());assertEquals(wire.required("request_id").textValue(),response.getHeader("X-Request-Id"));
  org.mockito.Mockito.when(cancellation.recover(admission,"original-key/?#-0000")).thenReturn(java.util.Optional.of(receipt));var recovered=controller.recover(http,new MockHttpServletResponse(),null);SchemaCatalogue.fromClasspath().validate("interfaces",recovered,"Envelope");schemas.validate("CancelRecovery",recovered.required("data"));assertEquals(receipt,recovered.required("data").required("receipt"));
 }
}
